const allData = $input.all();

// 합산할 변수 초기화
let report = {
  total_sales: 0,
  uber_commission: 0,
  stripe_fee: 0
  // 필요한 재무 항목 추가
};

allData.forEach(item => {
  const row = item.json;

  // 1. POS 데이터 판별 (예: '일매출합계' 컬럼이 존재하면)
  if (row['일매출합계'] !== undefined) {
    report.total_sales += parseFloat(row['일매출합계'] || 0);
  }
  // 2. Uber 데이터 판별
  else if (row['ubereats_commission'] !== undefined) {
    report.uber_commission += parseFloat(row['ubereats_commission'] || 0);
  }
  // 3. Stripe 데이터 판별
  else if (row['stripe_fee'] !== undefined) {
    report.stripe_fee += parseFloat(row['stripe_fee'] || 0);
  }
});

// 최종 계산된 1개의 리포트 데이터만 다음 AI 노드로 전달
return [{ json: report }];

