const now = new Date();
const etNow = new Date(now.getTime() - 5 * 60 * 60 * 1000);
const yyyy = etNow.getUTCFullYear();
const mm   = String(etNow.getUTCMonth() + 1).padStart(2, '0');
const dd   = String(etNow.getUTCDate()).padStart(2, '0');
const dateStr = `${yyyy}_${mm}_${dd}`;

// 구글 드라이브 API용 단일 통합 쿼리 생성
const driveQuery = `name = 'pos_${dateStr}.csv' or name = 'ubereats_${dateStr}.csv' or name = 'stripe_${dateStr}.csv'`;

return [{
  json: {
    driveQuery,
    dateDisplay: `${yyyy}-${mm}-${dd}`,
    dateStr
  }
}];

// 실제 파일 ID(id)가 존재하는 데이터만 필터링
const files = $('Search files and folders').all().filter(f => f.json.id);

if (files.length === 3) {
  return files;
} else {
  return [{ json: { error: true, count: files.length } }];
}
